import{_ as e,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"Mybatis 框架快速入门","description":"","frontmatter":{"title":"Mybatis 框架快速入门","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 框架快速入门.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 框架快速入门.md"}'),i={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 框架快速入门.md"};function l(a,t,d,p,n,c){return o(),r("div",null,[...t[0]||(t[0]=[s('<div><p><code>Mybatis</code> <strong>框架开发的准备</strong></p><p><strong>官网下载</strong> <code>Mybatis</code> <strong>框架</strong> 从百度中“<code>mybatis download</code>”可以下载最新的 <code>Mybatis</code> 开发包。 进入选择语言的界面，进入中文版本的开发文档。 下载相关的</p><p><code>jar</code></p><p>包或 <code>maven</code> 开发的坐标。 下载的</p><p><code>zip</code></p><p>文件如下（ 我们的资料文件夹）： 我们所使用的</p><p><code>Mybatis</code></p><p>版本是 <code>3.4.5</code> 版本。</p><p><strong>搭建</strong> <code>Mybatis</code> <strong>开发环境</strong></p><p><strong>当我们遵从了第三、四、五点之后，我们在开发中就无须再写<strong><strong>dao</strong></strong>的实现类</strong></p><p><strong>创建</strong> <code>maven</code> <strong>工程</strong> 创建</p><p><code>mybatis01</code></p><p>的工程，工程信息如下：</p><ul><li>Groupid:com.itheima</li><li>ArtifactId:mybatis01</li><li>Packing:jar</li></ul><p>添加 <code>Mybatis3.4.5</code> 的坐标 在</p><p><code>pom.xml</code></p><p>文件中添加 <code>Mybatis3.4.5</code> 的坐标，如下：</p><p>&lt;dependencies&gt; &lt;dependency&gt; &lt;groupId&gt;org.mybatis&lt;/groupId&gt; &lt;artifactId&gt;mybatis&lt;/artifactId&gt; &lt;version&gt;3.4.5&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;junit&lt;/groupId&gt; &lt;artifactId&gt;junit&lt;/artifactId&gt; &lt;version&gt;4.10&lt;/version&gt; &lt;scope&gt;test&lt;/scope&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;mysql&lt;/groupId&gt; &lt;artifactId&gt;mysql-connector-java&lt;/artifactId&gt; &lt;version&gt;5.1.6&lt;/version&gt; &lt;scope&gt;runtime&lt;/scope&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;log4j&lt;/groupId&gt; &lt;artifactId&gt;log4j&lt;/artifactId&gt; &lt;version&gt;1.2.12&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt; 2.2.3 <strong>编写</strong> <code>User</code> <strong>实体类</strong></p><p>/** *</p><ul><li>&lt;p&gt;Title: User&lt;/p&gt;</li><li>&lt;p&gt;Description: 用户的实体类</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ public class User implements Serializable { private Integer id; private String username; private Date birthday; private String sex; private String address; ￼</li></ul><p>public Integer getId() { return id; } public void setId(Integer id) { this.id = id; } public String getUsername() { return username; } public void setUsername(String username) { this.username = username; } public Date getBirthday() { return birthday; } public void setBirthday(Date birthday) { this.birthday = birthday; } public String getSex() { return sex; } public void setSex(String sex) { this.sex = sex; } public String getAddress() { return address; } public void setAddress(String address) { this.address = address; } @Override public String toString() { return &quot;User [id=&quot; + id + &quot;, username=&quot; + username + &quot;, birthday=&quot; + birthday</p><ul><li>&quot;, sex=&quot; + sex + &quot;, address=&quot;</li><li>address + &quot;]&quot;; } } <strong>编写持久层接口</strong></li></ul><ul><li>IUserDao</li><li>IUserDao</li></ul><p>接口就是我们的持久层接口（也可以写成 <code>UserDao</code> 或者</p><p><code>UserMapper</code></p><p>）<code>,</code>具体代码如下：</p><p>/**</p><ul><li>&lt;p&gt;Title: IUserDao&lt;/p&gt;</li><li>&lt;p&gt;Description: 用户的持久层操作</li></ul><p>&lt;/p&gt; <em>/ public interface IUserDao { /</em>* * 查询所有用户</p><ul><li>@return */ List&lt;User&gt; findAll(); } <strong>编写持久层接口的映射文件</strong> <code>IUserDao.xml</code><strong>要求：</strong> **创建位置：**必须和持久层接口在相同的包中。 **名称：**必须以持久层接口名称命名文件名，扩展名是<code>.xml</code></li></ul><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;!DOCTYPE mapper PUBLIC &quot;-<a href="//mybatis.org//DTD" target="_blank" rel="noreferrer">//mybatis.org//DTD</a> Mapper 3.0//EN&quot; &quot;<a href="http://mybatis.org/dtd/mybatis-3-mapper.dtd" target="_blank" rel="noreferrer">http://mybatis.org/dtd/mybatis-3-mapper.dtd</a>&quot;&gt; &lt;mapper namespace=&quot;com.itheima.dao.IUserDao&quot;&gt; &lt;!-- 配置查询所有操作</p><p>--&gt; &lt;select id=&quot;findAll&quot; resultType=&quot;com.itheima.domain.User&quot;&gt; select * from user &lt;/select&gt; &lt;/mapper&gt; <strong>编写</strong> <code>SqlMapConfig.xml</code> <strong>配置文件</strong></p><p>&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;!DOCTYPE configuration PUBLIC &quot;-<a href="//mybatis.org//DTD" target="_blank" rel="noreferrer">//mybatis.org//DTD</a> Config 3.0//EN&quot; &quot;<a href="http://mybatis.org/dtd/mybatis-3-config.dtd" target="_blank" rel="noreferrer">http://mybatis.org/dtd/mybatis-3-config.dtd</a>&quot;&gt; &lt;configuration&gt; &lt;!-- 配置 <code>mybatis</code> 的环境</p><ul><li>--&gt;</li><li>&lt;environments default=&quot;mysql&quot;&gt;</li><li>&lt;!--</li></ul><p>配置 <code>mysql</code> 的环境</p><ul><li>--&gt;</li><li>&lt;environment id=&quot;mysql&quot;&gt;</li><li>&lt;!--</li></ul><p>配置事务的类型</p><p>--&gt; &lt;transactionManager type=&quot;JDBC&quot;&gt;&lt;/transactionManager&gt; &lt;!-- 配置连接数据库的信息：用的是数据源<code>(</code>连接池</p><p>) --&gt; &lt;dataSource type=&quot;POOLED&quot;&gt; &lt;property name=&quot;driver&quot; value=&quot;com.mysql.jdbc.Driver&quot;/&gt; &lt;property name=&quot;url&quot; value=&quot;jdbc:mysql://localhost:3306/ee50&quot;/&gt; &lt;property name=&quot;username&quot; value=&quot;root&quot;/&gt; &lt;property name=&quot;password&quot; value=&quot;1234&quot;/&gt; &lt;/dataSource&gt; &lt;/environment&gt; &lt;/environments&gt; &lt;!-- 告知 <code>mybatis</code> 映射配置的位置</p><p>--&gt; &lt;mappers&gt; &lt;mapper resource=&quot;com/itheima/dao/IUserDao.xml&quot;/&gt; &lt;/mappers&gt; &lt;/configuration&gt; <strong>编写测试类</strong></p><p>/** *</p><ul><li>&lt;p&gt;Title: MybatisTest&lt;/p&gt;</li><li>&lt;p&gt;Description: 测试 <code>mybatis</code> 的环境</li></ul><p>&lt;/p&gt; */ public class MybatisTest { public static void main(String[] args)throws Exception { //1. 读取配置文件</p><p>InputStream in = Resources.getResourceAsStream(&quot;SqlMapConfig.xml&quot;); //2. 创建 <code>SqlSessionFactory</code> 的构建者对象</p><p>SqlSessionFactoryBuilder builder = new SqlSessionFactoryBuilder(); //3. 使用构建者创建工厂对象 <code>SqlSessionFactory</code> // 使用了构建者模式，这个模式把对象的创建细节隐藏， // 使使用者直接调用方法即可拿到对象</p><p>SqlSessionFactory factory = builder.build(in); //4. 使用 <code>SqlSessionFactory</code> 生产 <code>SqlSession</code> 对象 // 工厂模式：优势在解耦（降低类之间的依赖关系）</p><p>SqlSession session = factory.openSession(); //5. 使用 <code>SqlSession</code> 创建 <code>dao</code> 接口的代理对象 // 创建Dao接口实现类使用了代理模式 // 优势：不修改源码的基础上对已有方法增强</p><p>IUserDao userDao = session.getMapper(IUserDao.class); //6. 使用代理对象执行查询所有方法</p><p>List&lt;User&gt; users = userDao.findAll(); for(User user : users) { System.out.println(user); } //7. 释放资源</p><p>session.close(); in.close(); } } <strong>小结</strong> 通过快速入门示例，我们发现使用 <code>mybatis</code> 是非常容易的一件事情，因为只需要编写 <code>Dao</code> 接口并且按照<code>mybatis</code> 要求编写两个配置文件，就可以实现功能。远比我们之前的 <code>jdbc</code> 方便多了。（我们使用注解之后，将变得更为简单，只需要编写一个 <code>mybatis</code> 配置文件就够了。）</p><p>但是，这里面包含了许多细节，比如为什么会有工厂对象（<code>SqlSessionFactory</code>）<code>,</code>为什么有了工厂之后还要有构建者对象（<code>SqlSessionFactoryBuilder</code>），为什么 <code>IUserDao.xml</code> 在创建时有位置和文件名的要求等等。 这些问题我们在自定义</p><p><code>mybatis</code></p><p>框架的章节，通过层层剥离的方式，给大家讲解。 请注意：我们讲解自定义 <code>Mybatis</code> 框架，不是让大家回去自己去写个 <code>mybatis</code>，而是让我们能更好了了解<code>mybatis</code> 内部是怎么执行的，在以后的开发中能更好的使用 <code>mybatis</code> 框架，同时对它的设计理念（设计模式）有一个认识。</p><p><strong>补充（基于注解的</strong> <code>mybatis</code> <strong>使用）</strong></p><p><strong>在持久层接口中添加注解</strong></p><p>/** *</p><ul><li>&lt;p&gt;Title: IUserDao&lt;/p&gt;</li><li>&lt;p&gt;Description: 用户的持久层操作</li></ul><p>&lt;/p&gt; <em>/ public interface IUserDao { /</em>* * 查询所有用户</p><ul><li>@return */ @Select(&quot;select * from user&quot;) List&lt;User&gt; findAll(); } <strong>修改</strong></li></ul><ul><li>SqlMapConfig.xml</li><li>&lt;!--</li></ul><p>告知 <code>mybatis</code> 映射配置的位置</p><ul><li>--&gt;</li><li>&lt;mappers&gt;</li><li>&lt;mapper class=&quot;com.itheima.dao.IUserDao&quot;/&gt;</li><li>&lt;/mappers&gt;</li></ul><p><strong>注意事项：</strong> 在使用基于注解的</p><p><code>Mybatis</code></p><p>配置时，请移除 <code>xml</code> 的映射配置（<code>IUserDao.xml</code>）。</p><p>使用实现类操作数据</p></div>',1)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
